// Kasus sintetis adaptasi materi.html. Tiap kasus menghasilkan dua soal berbeda:
// keputusan dan evaluasi tindak lanjut. Opsi pertama adalah kunci sebelum rotasi.
// Setiap opsi disertai alasan agar pembahasan menjelaskan jebakan secara spesifik.
module.exports = [
{p:1,ref:'K-01',s:'Menjelang penutupan triwulan, tender Satker A batal dan RPD terkunci tidak sesuai realisasi. KPA meminta perubahan angka historis agar IKPA tetap baik. Beberapa SPM sah masih menunggu layanan.',
d:[['Pertahankan data terkunci, layani SPM sah, dan tugaskan verifikasi penyebab deviasi.','Memisahkan integritas data, layanan pembayaran, dan pembinaan perencanaan.'],['Tunda seluruh SPM sampai KPA memperbaiki nilai IKPA.','Pembinaan indikator tidak menjadi alasan menahan semua pembayaran sah.'],['Setujui penyesuaian histori setelah KPA menandatangani surat tanggung jawab.','Surat KPA tidak menggantikan mekanisme koreksi resmi.'],['Serahkan keputusan perubahan histori kepada operator aplikasi.','Delegasi teknis tidak memindahkan tanggung jawab pengendalian pimpinan.']],
m:[['Periksa rencana kegiatan baru, PIC, tenggat, dan kesesuaian realisasi periode berikutnya.','Keberhasilan dinilai dari perbaikan proses ke depan yang terverifikasi.'],['Pastikan warna indikator langsung berubah menjadi hijau.','Warna dapat berubah tanpa perbaikan akar masalah.'],['Hitung jumlah pesan pengingat yang dikirim ke satker.','Aktivitas komunikasi belum menunjukkan hasil.'],['Minta seluruh satker mengganti RPD dengan angka realisasi.','Menyeragamkan angka menghilangkan fungsi perencanaan.']]},
{p:1,ref:'K-05',s:'Dashboard menunjukkan belanja 75% dan output 40%. Tim menyebutnya pemborosan. KPA menjelaskan bahwa output baru diakui setelah laporan final disahkan, sedangkan biaya dibayar bulanan.',
d:[['Validasi profil output, bukti kemajuan, dan pola pembayaran sebelum menyimpulkan masalah.','Selisih rasio adalah sinyal yang memerlukan konteks.'],['Tetapkan pemborosan karena kedua persentase harus sama.','Hubungan belanja dan output tidak selalu linear.'],['Terima penjelasan KPA dan tutup kasus tanpa dokumen.','Penjelasan harus diuji dengan bukti.'],['Minta output dinaikkan agar sebanding dengan belanja.','Menyelaraskan angka tanpa prestasi menimbulkan risiko manipulasi.']],
m:[['Bandingkan milestone terverifikasi, jadwal pengakuan output, dan rencana koreksi bila tertinggal.','Ukuran hasil mengikuti karakter kegiatan dan bukti.'],['Tetapkan target seluruh output sama dengan rasio belanja.','Target mekanis mengabaikan profil output.'],['Nilai keberhasilan dari tidak adanya keluhan KPA.','Ketiadaan keluhan bukan bukti kualitas belanja.'],['Ukur jumlah unggahan laporan tanpa menelaah substansinya.','Kelengkapan unggahan tidak menjamin kemajuan nyata.']]},
{p:1,ref:'K-27',s:'KPA memprotes status Critical yang dianggap merusak citra satker. Tim menemukan potensi salah klasifikasi, tetapi belum memeriksa data sumber. KPA meminta label dihapus hari itu juga.',
d:[['Tugaskan verifikasi bukti dan catat koreksi jika sah; pertahankan risiko yang masih valid.','Objektivitas dan ruang koreksi dijaga bersamaan.'],['Hapus label sementara tanpa mencatat perubahan demi hubungan kerja.','Kompromi ini menghilangkan jejak keputusan.'],['Tolak semua keberatan karena sistem selalu objektif.','Sistem dapat salah dan perlu mekanisme keberatan.'],['Sebarkan tangkapan layar ke seluruh satker agar menjadi pelajaran.','Mempermalukan mitra bukan pembinaan yang proporsional.']],
m:[['Periksa bukti koreksi, versi rule, jejak perubahan, dan tindak lanjut risiko tersisa.','Pengendalian harus dapat ditelusuri.'],['Ukur keberhasilan dari berkurangnya jumlah status merah.','Jumlah merah dapat turun karena manipulasi klasifikasi.'],['Pastikan KPA tidak lagi mengirim protes.','Diamnya stakeholder tidak membuktikan akurasi.'],['Tutup laporan setelah administrator mengubah warna.','Perubahan tampilan belum membuktikan kesalahan sudah diperbaiki.']]},
{p:1,ref:'K-30',s:'Dua pegawai berpengalaman menangani antrean layanan sekaligus pembinaan satker. Seluruh alert dianggap mendesak. Kepala seksi saling meminta tambahan personel, sementara tenggat pembayaran mendekat.',
d:[['Prioritaskan berdasarkan urgensi dan dampak, bagi PIC, lalu sisihkan kapasitas pembinaan terarah.','Pimpinan mengelola kapasitas dan trade-off.'],['Hentikan seluruh pembinaan sampai antrean layanan selalu nol.','Risiko satker dapat terus membesar tanpa intervensi.'],['Undang seluruh satker ke rapat serentak minggu ini.','Intervensi massal belum sesuai kapasitas dan kebutuhan.'],['Kerjakan sendiri semua kasus penting agar tidak membebani staf.','Ketergantungan pada kepala kantor menghambat delegasi.']],
m:[['Tinjau umur antrean, kasus prioritas terselesaikan, beban PIC, dan risiko yang belum tertangani.','Metrik menilai keseimbangan layanan dan pembinaan.'],['Hitung hanya total surat tugas yang diterbitkan.','Penugasan belum membuktikan penyelesaian.'],['Gunakan jam lembur sebagai ukuran utama efektivitas.','Jam kerja tidak otomatis mencerminkan hasil.'],['Tutup semua alert yang belum ditangani pada akhir minggu.','Penutupan administratif menyembunyikan risiko.']]},
{p:1,ref:'IB-03',s:'Pilot EWS mengirim 300 notifikasi. Waktu respons satker belum berubah dan banyak penerima mengaku tidak tahu tindakan yang harus dilakukan. Tim mengusulkan perluasan karena delivery rate tinggi.',
d:[['Tahan perluasan, evaluasi kegunaan pesan dan alur penugasan, lalu uji ulang pilot terbatas.','Pengiriman pesan adalah output teknis, belum manfaat pembinaan.'],['Perluas segera karena jumlah notifikasi membuktikan adopsi.','Delivery tidak sama dengan adopsi atau hasil.'],['Tambah frekuensi pesan sampai satker merespons.','Frekuensi tanpa relevansi dapat memperparah kelelahan notifikasi.'],['Hentikan seluruh layanan MyIntress karena pilot belum berhasil.','Perbaikan pilot tidak mengharuskan penghentian layanan eksisting.']],
m:[['Bandingkan waktu verifikasi dan penyelesaian kasus sebanding, termasuk salah alert dan kendala pengguna.','Evaluasi mempertimbangkan manfaat serta efek samping.'],['Bandingkan jumlah email terkirim sebelum dan sesudah pilot.','Ukuran itu hanya menilai distribusi.'],['Ambil testimoni satu satker yang paling antusias.','Satu testimoni tidak mewakili variasi pengguna.'],['Gunakan kenaikan IKPA apa pun sebagai bukti kausal tunggal.','Perubahan IKPA dipengaruhi faktor lain.']]},
{p:2,ref:'K-02',s:'Pagu Satker B sebagian diblokir. Proyeksi penyerapan rendah dan KPA meminta status risiko dihapus. Tim pembinaan ingin memakai rekomendasi percepatan belanja yang sama untuk semua satker.',
d:[['Pisahkan pagu terblokir, pipeline siap, dan hambatan kewenangan sebelum menetapkan rekomendasi.','Diagnosis diperlukan agar pembinaan dapat ditindaklanjuti.'],['Perintahkan KPA menghabiskan seluruh pagu termasuk yang diblokir.','Target tidak menghapus kendala penggunaan anggaran.'],['Hilangkan seluruh risiko karena blokir selalu di luar kendali satker.','Masih ada risiko lain yang perlu dikelola.'],['Kepala KPPN membuka blokir langsung demi percepatan.','Advisory tidak memberi kewenangan membuka semua blokir.']],
m:[['Pantau tindak lanjut ke pihak berwenang dan realisasi pipeline yang memang dapat dijalankan.','Ukuran hasil membedakan ruang tindakan dan hambatan eksternal.'],['Nilai hanya persentase serapan total tanpa konteks blokir.','Kesimpulan dapat menyesatkan jika basis tidak dijelaskan.'],['Hitung seluruh anggaran terblokir sebagai output selesai.','Blokir bukan bukti capaian.'],['Pastikan semua satker mendapat jumlah konsultasi yang sama.','Kebutuhan pembinaan tidak seragam.']]},
{p:2,ref:'K-21',s:'Satker memiliki tagihan jatuh tempo, tetapi MP PNBP yang tersedia belum mencukupi. KPA meminta KPPN memproses karena penerimaan diperkirakan masuk minggu depan.',
d:[['Verifikasi ruang pembayaran dan data penerimaan, lalu arahkan tindak lanjut sesuai kewenangan tanpa melampaui MP.','Prediksi penerimaan belum menjadi otorisasi pembayaran.'],['Proses dahulu dengan jaminan pribadi KPA.','Jaminan pribadi tidak menggantikan batas penggunaan.'],['Ubah seluruh tagihan menjadi belanja rupiah murni di KPPN.','Perubahan sumber dana memerlukan mekanisme yang sah.'],['Tolak konsultasi karena masalah penerimaan sepenuhnya urusan satker.','KPPN tetap dapat memberi advisory yang sesuai mandat.']],
m:[['Periksa perubahan MP yang sah, prioritas tagihan, dan jadwal penyelesaian yang disepakati.','Tindak lanjut harus menghubungkan legalitas dan kebutuhan layanan.'],['Anggap seluruh proyeksi penerimaan sudah menambah MP.','Proyeksi tidak identik dengan otorisasi tersedia.'],['Tutup kasus ketika KPA mengirim surat permohonan.','Permohonan belum menjadi hasil penyelesaian.'],['Nilai keberhasilan dari banyaknya tagihan yang dipaksakan masuk.','Volume pengajuan tanpa kelayakan bukan keberhasilan.']]},
{p:2,ref:'K-08',s:'Retur SP2D berulang terjadi pada supplier yang sama di beberapa satker. Staf menyelesaikan satu per satu, tetapi kesalahan rekening muncul lagi pada pembayaran berikutnya.',
d:[['Tugaskan analisis pola data supplier dan koreksi terotorisasi, sambil menuntaskan retur yang valid.','Penyelesaian kasus dan pencegahan pengulangan harus berjalan bersama.'],['Ganti rekening dengan nomor yang diberikan lewat pesan informal.','Perubahan data penerima membutuhkan verifikasi.'],['Tutup seluruh retur setelah surat pemberitahuan terkirim.','Pemberitahuan belum berarti dana diterima pihak yang berhak.'],['Larangkan semua pembayaran kepada supplier tersebut tanpa pemeriksaan.','Pembatasan menyeluruh tidak proporsional terhadap bukti.']],
m:[['Ukur umur retur, keberhasilan penyelesaian, dan penurunan kesalahan rekening berulang.','Metrik menangkap hasil serta akar masalah.'],['Hitung jumlah surat retur sebagai capaian utama.','Banyak surat dapat justru menandakan pengulangan.'],['Gunakan jumlah rekening yang diubah tanpa validasi penerima.','Perubahan cepat dapat menambah risiko salah bayar.'],['Anggap SP2D terbit berarti seluruh pembayaran berhasil diterima.','Retur menunjukkan penerbitan bukan akhir proses.']]},
{p:2,ref:'K-17',s:'Puluhan transaksi berbeda tercatat sebagai TDK menjelang batas rekonsiliasi. Tim mengusulkan jurnal massal agar selisih nol. Sebagian perbedaan berasal dari waktu pencatatan yang belum sinkron.',
d:[['Kelompokkan penyebab, tetapkan PIC penelusuran, dan koreksi hanya berdasarkan dokumen sah.','Selisih harus dijelaskan, bukan sekadar dihilangkan.'],['Setujui jurnal penyeimbang untuk semua perbedaan.','Jurnal tanpa dasar dapat merusak laporan.'],['Nyatakan seluruh TDK sebagai kerugian negara.','Perbedaan pencatatan tidak otomatis membuktikan kerugian.'],['Tunggu sampai sistem menyelesaikan semuanya tanpa penugasan.','Sebagian selisih memerlukan tindakan aktif.']],
m:[['Periksa daftar selisih beserta sebab, bukti koreksi, saldo tersisa, dan umur penyelesaiannya.','Rekonsiliasi yang andal memiliki jejak penjelasan.'],['Cukup nilai apakah dashboard menampilkan nol selisih.','Nol tanpa bukti dapat berasal dari koreksi tidak sah.'],['Ukur jumlah jurnal yang dibuat per pegawai.','Banyak jurnal bukan ukuran akurasi.'],['Tutup semua selisih yang nilainya kecil tanpa telaah.','Nilai kecil tetap dapat menunjukkan kelemahan proses.']]},
{p:2,ref:'K-20',s:'PNBP lebih rendah dari target setelah perubahan tarif dan gangguan layanan. KPA ingin menaikkan tarif secara informal agar target tercapai. EWS masih memakai asumsi tarif lama.',
d:[['Validasi asumsi proyeksi dan dampak layanan, lalu arahkan opsi pemulihan sesuai kewenangan tarif.','Pimpinan harus membedakan perubahan kebijakan dan kinerja operasional.'],['Dukung kenaikan pungutan sementara untuk menutup target.','Target penerimaan tidak memberi hak memungut tanpa dasar.'],['Ubah realisasi menjadi sama dengan target agar model stabil.','Penyesuaian data tanpa transaksi adalah manipulasi.'],['Abaikan gangguan layanan karena hanya penerimaan yang dinilai.','Kualitas layanan dapat menjadi akar masalah penerimaan.']],
m:[['Pantau layanan pulih, asumsi tarif tervalidasi, dan proyeksi penerimaan yang dapat dijelaskan.','Evaluasi menguji penyebab, bukan hanya angka akhir.'],['Nilai hanya kenaikan tarif yang diusulkan KPA.','Usulan belum sah dan belum menunjukkan hasil.'],['Pastikan seluruh target diturunkan sampai indikator hijau.','Target tidak boleh disesuaikan semata untuk warna.'],['Gunakan jumlah pelanggan yang mengeluh sebagai penerimaan hilang pasti.','Keluhan memerlukan analisis, bukan konversi otomatis.']]},
{p:3,ref:'K-23',s:'Dokumen DAK Fisik beberapa OPD belum lengkap mendekati tenggat. Pemda meminta pencairan dahulu agar proyek tidak berhenti. Tim KPPN memiliki daftar kekurangan yang berbeda antar-OPD.',
d:[['Petakan kekurangan dan tenggat per OPD, lakukan asistensi terarah, dan jaga persyaratan penyaluran.','Pendampingan harus konkret tanpa menggantikan persyaratan.'],['Salurkan dahulu dan minta dokumen dilengkapi setelah tenggat.','Urgensi tidak otomatis membolehkan pelompatan syarat.'],['Buatkan sendiri seluruh dokumen teknis OPD.','KPPN tidak mengambil alih tanggung jawab teknis Pemda.'],['Kirim surat umum yang sama lalu hentikan komunikasi.','Kasus berbeda membutuhkan tindak lanjut yang spesifik.']],
m:[['Periksa pemenuhan syarat per OPD, PIC Pemda, tenggat, dan hambatan yang perlu eskalasi.','Ukuran hasil mengikuti titik kendali penyaluran.'],['Hitung hanya jumlah undangan rapat yang dikirim.','Undangan tidak membuktikan kesiapan dokumen.'],['Nilai keberhasilan dari seluruh permintaan yang disetujui.','Persetujuan tidak sah bukan keberhasilan.'],['Gunakan progres fisik sebagai pengganti semua syarat administratif.','Bukti fisik tidak otomatis menggantikan syarat lain.']]},
{p:3,ref:'K-24',s:'Banyak desa belum memenuhi syarat tahap penyaluran Dana Desa. Pemda meminta KPPN menghubungi setiap kepala desa sendiri karena kapasitas dinas terbatas.',
d:[['Sepakati daftar hambatan dan PIC Pemda, prioritaskan desa berisiko, serta pantau pemenuhan syarat.','Koordinasi memakai rantai tanggung jawab yang jelas.'],['Ambil alih verifikasi seluruh dokumen desa tanpa pembagian mandat.','Mengambil alih proses dapat melampaui kewenangan.'],['Tunda penyaluran semua desa hingga seluruh desa lengkap.','Kesiapan masing-masing penerima perlu dibedakan.'],['Abaikan hambatan karena pendampingan bukan tugas layanan.','Informasi dan asistensi tetap relevan dalam mandat KPPN.']],
m:[['Tinjau daftar desa eligible, kekurangan spesifik, dan penyelesaian menurut tenggat yang berlaku.','Monitoring menghindari penyamarataan kasus.'],['Nilai dari jumlah grup percakapan yang dibuat.','Media koordinasi bukan ukuran hasil.'],['Samakan status semua desa dengan desa yang paling lambat.','Agregasi ini menutup informasi kesiapan individual.'],['Anggap semua desa siap setelah Pemda menyatakan optimistis.','Optimisme harus didukung dokumen valid.']]},
{p:3,ref:'K-25',s:'Pemda mengalami tekanan kas APBD dan meminta Kepala KPPN menjamin pencairan transfer di luar jadwal. Kepala daerah menyebut hubungan baik sebagai alasan percepatan.',
d:[['Jelaskan batas mandat, validasi syarat transfer, dan koordinasikan persoalan fiskal dengan pihak berwenang.','Advisory tidak sama dengan menjamin dana di luar ketentuan.'],['Janjikan tanggal pencairan untuk menenangkan kepala daerah.','Janji tanpa kewenangan menimbulkan risiko layanan dan reputasi.'],['Gunakan kas negara sementara untuk menutup defisit APBD.','Kas tidak dapat dialihkan hanya berdasar kebutuhan mitra.'],['Tolak semua diskusi karena APBD bukan APBN.','Batas kewenangan tidak meniadakan koordinasi yang relevan.']],
m:[['Pastikan Pemda memahami opsi sah, syarat yang belum selesai, dan jalur eskalasi yang tepat.','Hasil advisory berupa keputusan mitra yang lebih terinformasi.'],['Nilai dari besarnya dana yang dijanjikan secara lisan.','Janji tidak menunjukkan realisasi sah.'],['Ukur hanya kepuasan kepala daerah terhadap jawaban cepat.','Kepuasan tidak menggantikan akurasi dan legalitas.'],['Minta KPPN menyusun ulang seluruh belanja APBD.','Peran tersebut berada pada otoritas Pemda.']]},
{p:3,ref:'PB-23',s:'Pemda memprotes perubahan proyeksi DBH dan meminta KPPN menghitung ulang alokasi final berdasarkan estimasi sendiri. Data realisasi salur dan dasar alokasi belum dipisahkan dalam bahan rapat.',
d:[['Pisahkan alokasi, realisasi salur, dan proyeksi; klarifikasi dasar angka ke pemilik kewenangan.','Informasi yang berbeda tidak boleh diperlakukan sebagai keputusan yang sama.'],['Tetapkan alokasi final sendiri dari angka realisasi terbaru.','KPPN tidak otomatis menjadi penetap alokasi.'],['Nyatakan seluruh proyeksi sebagai hak tagih pasti.','Proyeksi belum menjadi dasar penyaluran final.'],['Hapus seluruh data proyeksi agar tidak ada pertanyaan.','Menghilangkan informasi tidak menyelesaikan kebutuhan perencanaan.']],
m:[['Periksa konsistensi sumber, tanggal data, penjelasan perbedaan, dan tindak lanjut klarifikasi.','Kualitas advisory bergantung pada keterlacakan angka.'],['Nilai keberhasilan dari kesamaan seluruh angka pada slide.','Keseragaman dapat menyembunyikan perbedaan konsep.'],['Gunakan angka terbesar agar Pemda mudah menyusun rencana.','Optimisme tanpa dasar meningkatkan risiko perencanaan.'],['Tutup isu setelah rapat berlangsung tanpa catatan kesimpulan.','Pertemuan tanpa keputusan belum menyelesaikan ketidakjelasan.']]},
{p:3,ref:'K-23, PB-20',s:'Dua daerah meminta asistensi penyaluran pada hari yang sama. Daerah A tinggal satu dokumen yang dapat diperbaiki hari ini; Daerah B memiliki hambatan struktural dan tenggat lebih jauh. Tim hanya mampu satu kunjungan.',
d:[['Dahulukan intervensi yang mendesak dan dapat diselesaikan, sambil menetapkan eskalasi untuk hambatan B.','Prioritas mempertimbangkan urgensi, dampak, dan kelayakan tindakan.'],['Dahulukan daerah yang paling keras menyampaikan keluhan.','Tekanan komunikasi bukan satu-satunya dasar prioritas.'],['Bagi waktu sama persis tanpa menilai peluang penyelesaian.','Kesetaraan waktu tidak selalu efektif mengurangi risiko.'],['Tunda keduanya sampai semua pejabat tersedia.','Penundaan mengabaikan kesempatan perbaikan yang sempit.']],
m:[['Catat syarat A yang selesai dan progres eskalasi B, termasuk PIC serta tanggal reviu.','Setiap kasus memiliki ukuran hasil sesuai hambatannya.'],['Laporkan hanya bahwa satu kunjungan telah dilakukan.','Aktivitas tidak cukup menjelaskan manfaat.'],['Nilai keberhasilan dari banyaknya foto kunjungan.','Dokumentasi kegiatan bukan bukti pemenuhan syarat.'],['Tutup B karena tidak dipilih untuk kunjungan pertama.','Prioritas bukan alasan menghapus risiko yang tersisa.']]},
{p:4,ref:'K-26',s:'Penyaluran KUR/UMi wilayah rendah. Penyalur meminta Kepala KPPN menginstruksikan persetujuan calon debitur yang ditolak agar target wilayah tercapai.',
d:[['Petakan hambatan akses dan data, fasilitasi koordinasi, serta jaga keputusan kredit pada penyalur.','Fasilitasi tidak berarti mengambil alih penilaian kredit.'],['Perintahkan semua calon debitur disetujui demi target wilayah.','Target tidak menghapus tanggung jawab penyalur.'],['Jamin pelunasan calon debitur atas nama kantor.','Jaminan tersebut bukan kewenangan otomatis Kepala KPPN.'],['Hentikan koordinasi karena semua keputusan ada pada penyalur.','Masih ada ruang perbaikan akses dan informasi.']],
m:[['Periksa hambatan yang terselesaikan dan kualitas data, tanpa menjadikan persetujuan semua debitur sebagai target.','Hasil dinilai sesuai ruang kontribusi KPPN.'],['Nilai dari persentase debitur yang dipaksa lolos.','Persetujuan paksa mengabaikan kelayakan.'],['Anggap jumlah sosialisasi sama dengan akses pembiayaan membaik.','Sosialisasi perlu dihubungkan dengan hasil.'],['Minta petugas KPPN menggantikan analis kredit.','Peran pelaksana tidak dapat dipindahkan sembarangan.']]},
{p:4,ref:'K-22',s:'BLU memiliki kas tinggi, tetapi waktu tunggu layanan memburuk. Pengelola mengusulkan belanja besar agar saldo turun dan kinerja terlihat aktif.',
d:[['Analisis kebutuhan kas, hambatan layanan, dan manfaat belanja sebelum menyepakati langkah perbaikan.','Kas tinggi perlu konteks, bukan otomatis harus dihabiskan.'],['Dorong belanja sebesar mungkin untuk mengurangi saldo.','Pengurangan kas bukan tujuan layanan.'],['Nyatakan saldo tinggi pasti membuktikan efisiensi.','Saldo tinggi dapat berjalan bersama layanan buruk.'],['Ambil alih seluruh keputusan operasional BLU.','Advisory harus tetap menghormati kewenangan pengelola.']],
m:[['Pantau waktu tunggu, kapasitas layanan, dan kecukupan kas terhadap rencana perbaikan.','Ukuran menghubungkan sumber daya dengan manfaat layanan.'],['Gunakan penurunan saldo kas sebagai satu-satunya KPI.','Saldo turun belum berarti layanan membaik.'],['Hitung jumlah barang yang dibeli tanpa mengukur pemanfaatan.','Pengadaan adalah output, bukan manfaat akhir.'],['Nilai kepuasan hanya dari pegawai pengelola anggaran.','Penerima layanan perlu masuk evaluasi.']]},
{p:4,ref:'PB-26',s:'Data calon penerima pembiayaan pada sistem informasi berbeda dengan daftar penyalur. Target penyaluran mendekat dan operator mengusulkan menghapus data ganda tanpa konfirmasi.',
d:[['Tugaskan rekonsiliasi identitas dan jejak perubahan bersama pemilik data sebelum pemutakhiran.','Akurasi data harus ditopang bukti dan otorisasi.'],['Hapus seluruh data yang tampak mirip agar daftar bersih.','Kemiripan belum membuktikan duplikasi.'],['Gunakan daftar terbesar untuk menunjukkan potensi wilayah.','Besaran daftar tidak menjamin validitas.'],['Serahkan akun sistem ke penyalur agar memperbaiki langsung.','Berbagi akun merusak kontrol akses dan akuntabilitas.']],
m:[['Tinjau selisih terselesaikan dengan bukti identitas, otorisasi koreksi, dan kasus yang masih disengketakan.','Rekonsiliasi perlu jejak bukti, bukan sekadar angka sama.'],['Pastikan kedua daftar memiliki jumlah baris sama.','Jumlah sama tidak menjamin entitas sama.'],['Nilai dari banyaknya data yang dihapus.','Penghapusan dapat merusak data yang benar.'],['Anggap tidak ada keluhan berarti kualitas data baik.','Kesalahan tersembunyi dapat belum dilaporkan.']]},
{p:4,ref:'K-22, PB-15',s:'BLU meminta pendapat atas dua investasi alat layanan. Pilihan A lebih murah tetapi kapasitasnya tidak sesuai antrean; pilihan B lebih mahal dengan kebutuhan pemeliharaan besar. Kepala kantor diminta memilih tanpa kajian.',
d:[['Minta analisis kebutuhan, biaya siklus hidup, dan manfaat layanan untuk mendukung keputusan pejabat berwenang.','Advisory memperbaiki dasar keputusan, bukan sekadar memilih harga.'],['Pilih alat termurah agar pasti dinilai efisien.','Efisiensi memerlukan kesesuaian manfaat.'],['Pilih alat termahal karena pasti lebih modern.','Harga bukan bukti kebutuhan atau manfaat.'],['Tandatangani keputusan pengadaan menggantikan pengelola BLU.','Kewenangan pengadaan tidak beralih karena permintaan konsultasi.']],
m:[['Bandingkan pemanfaatan alat, biaya pemeliharaan, waktu tunggu, dan manfaat terhadap baseline.','Evaluasi harus menguji asumsi investasi.'],['Nilai investasi dari keberhasilan kontrak ditandatangani.','Kontrak belum menunjukkan manfaat operasional.'],['Gunakan nilai aset baru sebagai satu-satunya hasil.','Penambahan aset belum menjamin layanan.'],['Abaikan biaya pemeliharaan karena baru muncul tahun depan.','Biaya siklus hidup relevan sejak perencanaan.']]},
{p:4,ref:'K-26',s:'Program pembiayaan mencatat banyak peserta sosialisasi, tetapi pelaku usaha tetap kesulitan memenuhi persyaratan. Penyalur meminta acara serupa diulang tanpa evaluasi hambatan.',
d:[['Identifikasi titik kegagalan persyaratan dan susun pendampingan bersama pihak yang berwenang.','Intervensi diarahkan pada hambatan nyata.'],['Ulang acara dengan peserta lebih banyak sebagai indikator utama.','Skala aktivitas tidak menyelesaikan hambatan yang sama.'],['Minta seluruh persyaratan dihapus untuk kelompok peserta acara.','Pendampingan tidak membenarkan penghilangan kontrol.'],['Janji bahwa semua peserta akan memperoleh pembiayaan.','KPPN tidak menjamin keputusan pembiayaan individual.']],
m:[['Pantau kelengkapan pengajuan dan hambatan yang teratasi tanpa menjanjikan persetujuan kredit.','Ukuran sesuai ruang fasilitasi.'],['Ukur hanya jumlah sertifikat peserta yang dibagikan.','Sertifikat tidak menunjukkan akses membaik.'],['Hitung seluruh peserta sebagai debitur baru.','Partisipasi tidak sama dengan penyaluran.'],['Laporkan semua penolakan sebagai kesalahan penyalur.','Penolakan dapat memiliki dasar kelayakan.']]},
{p:5,ref:'K-10',s:'RPD Harian berulang kali jauh dari kebutuhan pembayaran aktual. Satker menyerahkan angka perkiraan kasar, sementara tim kas kesulitan menyiapkan proyeksi yang dapat dipercaya.',
d:[['Bina satker menggunakan jadwal tagihan yang tervalidasi dan tetapkan reviu penyimpangan berulang.','Proyeksi kas perlu bertumpu pada kebutuhan yang dapat dijelaskan.'],['Samakan RPD Harian dengan pagu tahunan dibagi hari kerja.','Pembagian rata mengabaikan pola tagihan.'],['Gunakan realisasi kemarin sebagai angka pasti hari ini.','Pola historis tidak otomatis mewakili kebutuhan baru.'],['Hentikan semua pembayaran sampai setiap proyeksi tepat.','Pengendalian proyeksi tidak membenarkan penghentian menyeluruh.']],
m:[['Tinjau deviasi proyeksi terhadap kebutuhan aktual beserta penyebab dan perbaikan sumber data.','Evaluasi mempertimbangkan akurasi serta pembelajaran.'],['Nilai dari ketepatan jumlah file RPD yang diterima.','Pengiriman file belum menjamin kualitas proyeksi.'],['Tutup deviasi dengan mengubah proyeksi setelah pembayaran.','Perubahan retrospektif menghilangkan ukuran akurasi.'],['Gunakan serapan tahunan sebagai pengganti akurasi harian.','Horizon dan tujuan pengukurannya berbeda.']]},
{p:5,ref:'K-19',s:'Saldo rekening bendahara meningkat tidak lazim menjelang akhir bulan. Satker menjelaskan ada pembayaran tertunda, tetapi rincian transaksi dan rekonsiliasi belum tersedia.',
d:[['Minta penelusuran saldo dan transaksi, verifikasi penjelasan, lalu tindak lanjuti sesuai hasil dan kewenangan.','Saldo tak lazim adalah sinyal, bukan kesimpulan akhir.'],['Nyatakan terjadi penyelewengan sebelum dokumen diperiksa.','Kesimpulan memerlukan bukti yang memadai.'],['Terima penjelasan lisan dan hentikan penelusuran.','Kontrol memerlukan data pendukung.'],['Pindahkan seluruh saldo ke rekening lain atas arahan informal.','Pemindahan dana harus memiliki dasar dan otorisasi.']],
m:[['Pastikan saldo dapat direkonsiliasi dan setiap transaksi tidak biasa memiliki bukti serta tindak lanjut.','Akuntabilitas dinilai dari penjelasan yang dapat diuji.'],['Nilai dari saldo yang turun ke nol apa pun caranya.','Saldo nol dapat diperoleh melalui tindakan tidak sah.'],['Tutup kasus setelah bendahara diganti.','Pergantian personel tidak menyelesaikan transaksi lama.'],['Ukur jumlah permintaan dokumen tanpa menelaah hasilnya.','Permintaan bukti bukan penyelesaian bukti.']]},
{p:5,ref:'PB-12',s:'Satker mengaku telah menyetor penerimaan, tetapi status pada sistem belum cocok dengan bukti yang dibawa. Pengguna meminta petugas menerbitkan konfirmasi manual agar layanan cepat selesai.',
d:[['Validasi identitas setoran dan status pada sumber berwenang sebelum memberikan konfirmasi.','Bukti pengguna harus direkonsiliasi dengan data penerimaan.'],['Terbitkan konfirmasi berdasarkan tangkapan layar saja.','Tangkapan layar belum memastikan setoran sah dan cocok.'],['Minta pengguna menyetor ulang tanpa menelusuri transaksi awal.','Tindakan itu berisiko menimbulkan pembayaran ganda.'],['Ubah identitas setoran agar sesuai dengan permintaan.','Koreksi data memerlukan mekanisme sah.']],
m:[['Cek kecocokan transaksi, hasil penelusuran, dan penyelesaian selisih melalui prosedur yang berlaku.','Hasil harus dapat ditelusuri ke transaksi sumber.'],['Hitung jumlah konfirmasi manual yang diterbitkan.','Kecepatan penerbitan tidak menjamin validitas.'],['Nilai dari hilangnya antrean meski status belum jelas.','Antrean berkurang belum berarti transaksi terselesaikan.'],['Anggap seluruh kelambatan sebagai kesalahan pengguna.','Penyebab dapat berada pada integrasi atau pencatatan.']]},
{p:5,ref:'PB-10',s:'Kas pada satu rekening operasional terlihat besar ketika rekening lain menghadapi kebutuhan pembayaran. Tim mengusulkan pemindahan langsung tanpa menelaah otorisasi dan mekanisme pengelolaan kas.',
d:[['Validasi kebutuhan, posisi kas, serta jalur otorisasi, lalu koordinasikan tindakan dengan pengelola berwenang.','Optimalisasi kas tetap mengikuti tata kelola.'],['Pindahkan dana segera karena semuanya milik negara.','Kepemilikan negara tidak menghapus pembatasan kewenangan.'],['Biarkan dana menganggur tanpa menyampaikan kebutuhan pembayaran.','Pimpinan tetap perlu mengoordinasikan solusi.'],['Gunakan rekening pribadi sementara agar pembayaran lancar.','Solusi itu meniadakan kontrol rekening pemerintah.']],
m:[['Pantau kecukupan kas, pembayaran sah, dan dokumentasi otorisasi tindakan pengelolaan kas.','Keandalan layanan dan kepatuhan harus terukur bersama.'],['Nilai hanya berapa cepat saldo berpindah.','Kecepatan bukan bukti otorisasi.'],['Tetapkan saldo semua rekening harus sama setiap hari.','Kebutuhan dan fungsi rekening berbeda.'],['Ukur hanya jumlah telepon koordinasi antarunit.','Koordinasi belum membuktikan hasil kas.']]},
{p:5,ref:'K-08, PB-11',s:'Retur gaji menyangkut banyak pegawai. Pengguna mendesak pembayaran alternatif, sementara kesalahan data rekening belum tervalidasi. Tim berencana memakai rekening kolektif tanpa pemeriksaan.',
d:[['Prioritaskan verifikasi penerima dan perbaikan melalui mekanisme sah dengan PIC serta komunikasi status.','Urgensi perlu percepatan terkendali, bukan penghilangan verifikasi.'],['Alihkan ke rekening kolektif berdasarkan persetujuan lisan.','Persetujuan lisan tidak memastikan hak penerima dan otorisasi.'],['Tunda seluruh komunikasi sampai semua retur selesai.','Pengguna memerlukan informasi status yang jujur.'],['Terbitkan pembayaran ulang tanpa memastikan status transaksi awal.','Risiko pembayaran ganda harus dikendalikan.']],
m:[['Pantau penerima yang telah memperoleh hak, retur tersisa, dan pencegahan transaksi ganda.','Ukuran hasil berorientasi pada penerima yang sah.'],['Nyatakan selesai setelah pengajuan ulang dibuat.','Pengajuan belum sama dengan penerimaan dana.'],['Nilai dari hilangnya pemberitaan negatif.','Reputasi bukan bukti penyelesaian pembayaran.'],['Hitung semua rekening kolektif sebagai penyelesaian individual.','Cara tersebut tidak membuktikan hak tiap penerima terpenuhi.']]},
{p:6,ref:'K-17',s:'Menjelang penyusunan laporan, satu kelompok TDK berulang tiga bulan. Staf selalu memperbaiki angka akhir, tetapi tidak ada catatan penyebab atau perbaikan alur sumber.',
d:[['Tugaskan analisis akar kesalahan berulang dan perbaikan kontrol sumber selain koreksi periode berjalan.','Pimpinan perlu mencegah pengulangan, bukan hanya menutup periode.'],['Pertahankan koreksi manual karena laporan selalu selesai.','Ketepatan waktu dapat menutupi kelemahan berulang.'],['Hapus transaksi bermasalah dari ruang lingkup rekonsiliasi.','Penghilangan ruang lingkup menyembunyikan selisih.'],['Ganti semua operator tanpa menelaah proses.','Masalah dapat bersifat sistemik, bukan personal.']],
m:[['Periksa penurunan selisih berulang dan uji apakah kontrol baru mencegah salah catat.','Monitoring menilai efektivitas perbaikan.'],['Hitung banyaknya koreksi manual sebagai produktivitas.','Koreksi tinggi dapat menunjukkan proses buruk.'],['Nilai hanya tanggal laporan dikirim.','Ketepatan waktu tidak cukup untuk menilai keandalan.'],['Anggap masalah selesai setelah SOP ditandatangani.','SOP perlu diterapkan dan diuji.']]},
{p:6,ref:'K-18',s:'Capaian output dilaporkan tinggi, tetapi klasifikasi akun dan dokumen aktivitas tidak konsisten. KPA meminta laporan segera diteruskan karena waktu penyampaian hampir habis.',
d:[['Tugaskan penelusuran hubungan dokumen, akun, dan output; lakukan koreksi sah serta jelaskan isu terbuka.','Keandalan laporan tidak boleh dikorbankan untuk tampilan capaian.'],['Teruskan semua data tanpa catatan agar tenggat terpenuhi.','Masalah diketahui harus ditangani secara transparan.'],['Ubah kode akun massal tanpa melihat transaksi.','Klasifikasi memerlukan substansi dan bukti.'],['Turunkan semua output ke nol untuk menghindari kesalahan.','Koreksi menyeluruh tanpa bukti juga tidak andal.']],
m:[['Uji sampel konsistensi dokumen-akun-output dan tindak lanjut perbedaan yang belum selesai.','Validitas membutuhkan penelusuran lintas data.'],['Gunakan persentase output tertinggi sebagai ukuran keberhasilan.','Angka tinggi belum berarti akurat.'],['Periksa hanya jumlah halaman laporan.','Volume laporan tidak menunjukkan keandalan.'],['Tutup temuan ketika satker menyatakan data sudah bagus.','Pernyataan perlu verifikasi.']]},
{p:6,ref:'PB-18',s:'Laporan Kuasa BUN memuat angka yang berubah setelah penutupan internal. Tim tidak mencatat versi data sehingga dua bahan rapat menunjukkan saldo berbeda.',
d:[['Tetapkan rekonsiliasi versi, sumber dan waktu data, serta otorisasi koreksi sebelum laporan disahkan.','Pengendalian versi menjaga konsistensi dan jejak audit.'],['Pilih angka terbaru tanpa memeriksa alasan perubahan.','Kebaruan saja tidak menjamin akurasi.'],['Pilih angka yang paling baik untuk citra kantor.','Pelaporan tidak boleh mengikuti kepentingan citra.'],['Larangkan semua koreksi walaupun kesalahan terbukti.','Koreksi sah tetap diperlukan dengan jejak yang jelas.']],
m:[['Pastikan setiap perubahan memiliki sumber, alasan, persetujuan, dan rekonsiliasi ke laporan final.','Jejak perubahan memungkinkan laporan dipertanggungjawabkan.'],['Nilai dari kesamaan warna grafik di semua slide.','Konsistensi visual bukan konsistensi data.'],['Hapus seluruh versi sebelumnya tanpa catatan.','Riwayat diperlukan untuk menelusuri koreksi.'],['Ukur jumlah revisi serendah mungkin walaupun salah belum diperbaiki.','Minim revisi bukan tujuan bila laporan tidak andal.']]},
{p:6,ref:'PB-16',s:'Satker menerima hibah barang dan mulai menggunakannya, tetapi dokumen pengakuan dan pencatatan belum lengkap. Tim meminta KPPN menilai nominal sendiri agar laporan segera seimbang.',
d:[['Arahkan pemenuhan dokumen dan penilaian oleh pihak berwenang sebelum pencatatan sesuai mekanisme.','Pengakuan dan nilai harus memiliki dasar yang sah.'],['Tentukan nilai perkiraan Kepala KPPN tanpa bukti.','Perkiraan pribadi tidak menggantikan dasar penilaian.'],['Abaikan barang karena tidak melalui pembayaran APBN.','Tidak adanya pembayaran tidak otomatis meniadakan kewajiban pencatatan.'],['Catat sebagai kas agar neraca mudah disusun.','Klasifikasi harus mengikuti substansi aset.']],
m:[['Periksa kelengkapan dasar pengakuan, kewajaran nilai yang didukung bukti, dan konsistensi catatan aset.','Keandalan akuntansi memerlukan dasar dan rekonsiliasi.'],['Gunakan keseimbangan total neraca sebagai satu-satunya ukuran.','Seimbang secara aritmetika belum berarti benar.'],['Pastikan barang sudah difoto tanpa dokumen lain.','Foto tidak menggantikan dokumen pengakuan dan penilaian.'],['Nilai keberhasilan dari besarnya aset tambahan.','Nilai besar tidak menjamin pencatatan sah.']]},
{p:6,ref:'K-19, PB-18',s:'Ada saldo yang belum dapat dijelaskan pada laporan bendahara. Pimpinan satker ingin menyatakan kasus sebagai kerugian final agar penyelesaian cepat, padahal bukti masih ditelusuri.',
d:[['Pisahkan selisih pencatatan, dugaan penyimpangan, dan penetapan kerugian melalui pemeriksaan yang berwenang.','Tahap dan status bukti tidak boleh dicampur.'],['Tetapkan kerugian final dari selisih dashboard saja.','Selisih belum membuktikan unsur kerugian final.'],['Hapus saldo karena belum ada kepastian.','Ketidakpastian bukan alasan menghilangkan catatan.'],['Tutup penelusuran setelah bendahara berjanji mengganti.','Janji tidak menyelesaikan pembuktian dan prosedur.']],
m:[['Pantau bukti yang diperoleh, koreksi yang sah, dan eskalasi sesuai status temuan.','Monitoring mengikuti perkembangan pembuktian.'],['Anggap semua penggantian sukarela membuktikan proses selesai.','Pemulihan dana dan prosedur pertanggungjawaban perlu dibedakan.'],['Nilai dari seberapa cepat seseorang ditetapkan bersalah.','Kecepatan vonis bukan kualitas pengendalian.'],['Hentikan monitoring saat kasus masuk berita acara awal.','Berita acara awal bukan akhir penyelesaian.']]},
{p:7,ref:'K-03',s:'Belanja modal tertinggal. Satker ingin mengajukan pembayaran walau barang belum diterima dan bukti prestasi belum tersedia. Kepala kantor didesak membantu target serapan wilayah.',
d:[['Jaga pengujian pembayaran dan arahkan penyelesaian hambatan kegiatan kepada KPA/PPK.','Orientasi hasil harus tetap menjaga hak tagih dan kewenangan.'],['Proses pembayaran dengan janji barang segera datang.','Janji tidak menggantikan bukti dan mekanisme sah.'],['Ambil alih penilaian prestasi kontrak dari PPK.','Tanggung jawab substantif kontrak tetap pada pejabat berwenang.'],['Ubah status EWS menjadi normal agar tekanan berhenti.','Perubahan status tanpa dasar menyembunyikan risiko.']],
m:[['Pantau milestone kontrak, bukti prestasi, kelengkapan tagihan, dan pembayaran yang sah.','Target layanan harus dihubungkan dengan kesiapan hak tagih.'],['Gunakan serapan 100% sebagai satu-satunya KPI.','Serapan tanpa kualitas dan kepatuhan tidak cukup.'],['Hitung hanya jumlah SPM yang masuk antrean.','Pengajuan belum membuktikan tagihan layak.'],['Nilai dari banyaknya dispensasi yang diberikan.','Dispensasi bukan ukuran kualitas pelaksanaan.']]},
{p:7,ref:'K-09',s:'Bendahara baru belum memahami pertanggungjawaban UP/TUP. Tenggat mendekat dan pejabat satker meminta tambahan dana agar kegiatan terus berjalan tanpa menuntaskan administrasi sebelumnya.',
d:[['Verifikasi posisi pertanggungjawaban, beri asistensi spesifik, dan arahkan langkah sah sesuai kondisi dana.','Pembinaan perlu menyelesaikan hambatan tanpa mengabaikan kontrol.'],['Setujui tambahan dana otomatis karena bendahara masih baru.','Keterbatasan kompetensi tidak menghapus persyaratan.'],['Kerjakan semua pertanggungjawaban satker menggunakan akun bendahara.','Pendampingan tidak berarti mengambil alih akun dan tanggung jawab.'],['Hentikan seluruh konsultasi sampai dokumen lengkap.','Asistensi justru diperlukan agar syarat terpenuhi.']],
m:[['Tinjau dokumen yang benar-benar selesai, pemahaman bendahara, dan risiko pengulangan tenggat.','Hasil pembinaan meliputi kepatuhan dan kapasitas.'],['Hitung jumlah peserta bimbingan tanpa memeriksa hasil kerja.','Kehadiran tidak menjamin kompetensi.'],['Anggap tambahan dana sebagai bukti masalah selesai.','Dana tambahan dapat menambah risiko yang belum diselesaikan.'],['Nilai hanya kecepatan operator KPPN mengisi data satker.','Pengambilalihan pekerjaan bukan ukuran kemandirian satker.']]},
{p:7,ref:'K-14',s:'Kontrak belum selesai menjelang akhir tahun. PPK meminta seluruh sisa nilai kontrak ditempatkan dalam RPATA, tanpa menelaah jenis pekerjaan dan kelengkapan syarat.',
d:[['Tugaskan pemeriksaan kelayakan mekanisme dan dokumen; jelaskan beda penampungan, pembayaran, serta penihilan.','RPATA memerlukan syarat dan tindak lanjut, bukan jalan pintas umum.'],['Setujui semua kontrak terlambat karena sama-sama akhir tahun.','Kelayakan tidak otomatis sama untuk semua pekerjaan.'],['Anggap penampungan berarti penyedia telah berhak atas seluruh dana.','Penampungan dan pembayaran atas prestasi berbeda.'],['Minta KPPN menyatakan pekerjaan selesai menggantikan PPK.','Penilaian prestasi tidak berpindah ke KPPN.']],
m:[['Pantau syarat, status pekerjaan, pembayaran sah, saldo penampungan, dan tindak lanjut penihilan.','Monitoring mengikuti seluruh siklus, bukan hanya masuk rekening.'],['Nyatakan selesai segera setelah dana ditampung.','Penampungan masih memerlukan penyelesaian berikutnya.'],['Gunakan nilai penampungan terbesar sebagai keberhasilan.','Nilai besar tidak menunjukkan ketepatan penggunaan mekanisme.'],['Abaikan saldo setelah tahun anggaran berganti.','Saldo tetap memerlukan pengendalian.']]},
{p:7,ref:'K-15',s:'Tanggal BAST pada tagihan tidak konsisten dengan kronologi pekerjaan. Pengguna menekan petugas agar cepat memproses karena pimpinan satker telah menyetujui dokumen.',
d:[['Lakukan klarifikasi terarah atas kejanggalan melalui pejabat berwenang dan dokumentasikan hasil pengujian.','Persetujuan atasan tidak meniadakan kejanggalan yang perlu ditelaah.'],['Proses langsung karena dokumen telah ditandatangani KPA.','Tanda tangan bukan alasan mengabaikan anomali.'],['Tolak semua tagihan satker untuk waktu tak terbatas.','Respons harus proporsional pada masalah yang diperiksa.'],['Ganti tanggal pada salinan agar sesuai kronologi.','Petugas tidak boleh mengubah bukti untuk meloloskan tagihan.']],
m:[['Periksa jawaban klarifikasi, dokumen sah, keputusan layanan, dan jejak penanganan tekanan.','Akuntabilitas membutuhkan alasan keputusan yang dapat diuji.'],['Nilai dari kecepatan tagihan tersebut cair.','Kecepatan tidak membuktikan keabsahan.'],['Tutup anomali setelah ada telepon pejabat senior.','Pengaruh hierarki tidak menggantikan bukti.'],['Ukur hanya berkurangnya keluhan satker.','Keluhan turun belum membuktikan kontrol bekerja.']]},
{p:7,ref:'K-06',s:'SPM satker ditolak lima kali karena kesalahan yang sama. Tim mengirim kode penolakan standar setiap kali, sementara KPA menyebut layanan KPPN mempersulit.',
d:[['Petakan akar kesalahan dan lakukan asistensi pada pejabat pengampu, sambil menjaga standar pengujian.','Layanan perlu membantu perbaikan tanpa menurunkan kontrol.'],['Loloskan pengajuan berikutnya agar keluhan berhenti.','Pengulangan kesalahan tidak menjadi alasan menghapus pengujian.'],['Kirim penolakan yang sama tanpa menjelaskan langkah koreksi.','Komunikasi yang tidak operasional memperpanjang masalah.'],['Ambil alih seluruh penyusunan SPM satker.','Tanggung jawab satker tidak dipindahkan ke pemberi layanan.']],
m:[['Pantau pengajuan ulang yang benar, penurunan kesalahan berulang, dan pemahaman pejabat satker.','Ukuran hasil adalah perbaikan kemampuan dan kualitas dokumen.'],['Hitung jumlah penolakan sebagai prestasi pengawasan.','Penolakan berulang dapat menunjukkan pembinaan belum efektif.'],['Ukur hanya jumlah konsultasi tanpa hasil dokumen.','Konsultasi belum membuktikan masalah teratasi.'],['Nilai dari semua SPM diterima tanpa memeriksa kelayakan.','Penerimaan tanpa kontrol menambah risiko.']]},
{p:8,ref:'K-28',s:'Data sumber terlambat dua jam, tetapi dashboard EWS memberi warna hijau pada satker yang datanya kosong. Tim ingin memakai ringkasan itu untuk rapat pimpinan.',
d:[['Tandai data belum tersedia, validasi snapshot yang sah, dan pisahkan gangguan data dari risiko satker.','Ketiadaan data tidak sama dengan risiko normal.'],['Gunakan warna hijau karena tidak ada temuan yang terbaca.','Kesimpulan tersebut mengubah ketidaktahuan menjadi kepastian palsu.'],['Isi data kosong dengan nol agar grafik lengkap.','Nilai nol dapat menyesatkan klasifikasi.'],['Hentikan semua layanan pembayaran karena satu dashboard terlambat.','Dampak harus dipetakan sebelum penghentian menyeluruh.']],
m:[['Periksa timestamp, kelengkapan sumber, hasil pemulihan, dan validitas klasifikasi setelah sinkronisasi.','Keandalan dinilai dari kualitas informasi dan pemulihan.'],['Nilai hanya banyaknya indikator hijau setelah proses ulang.','Warna tidak membuktikan sumber valid.'],['Anggap berhasil bila dashboard bisa dibuka.','Ketersediaan tampilan berbeda dari kualitas data.'],['Ukur jumlah refresh yang dilakukan operator.','Refresh tidak otomatis memulihkan sumber.']]},
{p:8,ref:'K-29',s:'Email EWS terkirim kepada pejabat yang sudah mutasi. Daftar penerima berasal dari data lama dan pesan memuat rincian satker. Tim ingin sekadar menghapus alamat dari daftar berikutnya.',
d:[['Tangani sebagai insiden sesuai prosedur, batasi dampak, verifikasi penerima, dan perbaiki siklus hak akses.','Salah kirim memerlukan respons insiden dan pencegahan.'],['Hapus alamat lama tanpa mencatat kejadian.','Akar dan dampak insiden tetap perlu ditangani.'],['Kirim seluruh data ke grup yang lebih luas agar pejabat baru melihatnya.','Penyebaran lebih luas memperbesar paparan.'],['Anggap aman karena penerima lama pernah berwenang.','Kewenangan harus sesuai penugasan saat ini.']],
m:[['Uji daftar penerima aktif, otorisasi tautan, log distribusi, dan hasil tindak lanjut insiden.','Kontrol perlu dibuktikan bekerja setelah koreksi.'],['Gunakan delivery rate sebagai satu-satunya indikator keamanan.','Pesan terkirim belum tentu ke penerima sah.'],['Nilai dari tidak adanya balasan penerima lama.','Diam tidak membuktikan data tidak terpapar.'],['Hapus semua log agar data insiden tidak tersebar.','Log diperlukan untuk penelusuran yang terkontrol.']]},
{p:8,ref:'K-11',s:'SPAN/SAKTI mengalami gangguan ketika tenggat layanan mendekat. Pengguna meminta petugas memakai akun bersama dan prosedur tidak tercatat agar transaksi tetap berjalan.',
d:[['Aktifkan penanganan insiden dan kontinjensi yang sah, komunikasikan status, serta koordinasikan pemulihan.','Kontinuitas layanan harus menjaga kontrol dan jejak audit.'],['Izinkan akun bersama sementara sampai gangguan selesai.','Akun bersama menghilangkan akuntabilitas tindakan.'],['Catat transaksi di luar mekanisme tanpa rencana rekonsiliasi.','Solusi sementara tetap membutuhkan kontrol dan pemulihan.'],['Janjikan waktu pulih pasti tanpa konfirmasi pengelola sistem.','Janji yang tidak berdasar merusak kepercayaan layanan.']],
m:[['Pantau waktu pulih, antrean transaksi, rekonsiliasi pascapulih, dan komunikasi ke pengguna.','Pemulihan teknis harus diikuti pemulihan proses bisnis.'],['Nyatakan selesai ketika halaman login kembali tampil.','Login berfungsi belum membuktikan transaksi pulih.'],['Nilai dari semua keluhan dihapus dari helpdesk.','Penghapusan catatan menyembunyikan dampak.'],['Gunakan jumlah percobaan login sebagai produktivitas.','Percobaan login bukan hasil layanan.']]},
{p:8,ref:'IB-03',s:'Rule prediksi baru diuji menggunakan data yang sebagian baru diketahui setelah tanggal prediksi. Hasil tampak sangat akurat dan tim meminta izin langsung ke produksi.',
d:[['Tahan penerapan, lakukan pengujian berdasarkan waktu dan validasi data yang benar-benar tersedia saat prediksi.','Pengujian harus menghindari kebocoran informasi masa depan.'],['Setujui karena akurasi tinggi cukup membuktikan model baik.','Hasil dapat bias karena desain uji.'],['Ubah label data uji agar model makin akurat.','Label tidak boleh direkayasa demi skor.'],['Hilangkan semua prediksi karena model tidak pernah boleh salah.','Model memerlukan pengukuran ketidakpastian, bukan tuntutan sempurna.']],
m:[['Tinjau precision, recall, salah alert, dan performa pada periode uji yang terpisah secara waktu.','Evaluasi menilai generalisasi dan biaya kesalahan.'],['Nilai hanya akurasi pada data pelatihan.','Kinerja pada data yang dikenal dapat terlalu optimistis.'],['Gunakan kepuasan pengembang sebagai pengganti validasi.','Keyakinan pembuat bukan bukti performa.'],['Ukur jumlah rule yang aktif tanpa memeriksa kualitas sinyal.','Banyak rule dapat menambah noise.']]},
{p:8,ref:'M3, IB-03',s:'Pilot disukai pengguna, tetapi uji hak akses menunjukkan pengguna satu KPPN bisa membuka rincian satker KPPN lain tanpa otorisasi. Jadwal peluncuran sudah diumumkan.',
d:[['Tunda perluasan, perbaiki batas akses, dan wajibkan uji ulang sebelum keputusan go.','Keamanan akses tidak dapat ditukar dengan kepuasan atau jadwal.'],['Luncurkan sesuai jadwal dan perbaiki setelah ada keluhan.','Paparan yang diketahui harus dikendalikan sebelum perluasan.'],['Minta pengguna berjanji tidak membuka data kantor lain.','Janji tidak menggantikan kontrol otorisasi.'],['Sembunyikan tombol rincian tetapi biarkan endpoint terbuka.','Kontrol antarmuka saja tidak melindungi akses data.']],
m:[['Minta bukti uji akses positif-negatif, perbaikan akar celah, dan persetujuan pihak berwenang.','Keputusan go memerlukan evidensi teknis dan tata kelola.'],['Nilai dari turunnya jumlah tombol yang terlihat.','Tampilan tidak membuktikan pembatasan backend.'],['Gunakan jumlah pengguna puas sebagai bukti keamanan.','Kepuasan dan keamanan mengukur hal berbeda.'],['Tutup temuan setelah pengembang menyatakan sudah diperbaiki.','Perbaikan harus diverifikasi melalui pengujian ulang.']]},
{p:9,ref:'K-13',s:'Laporan progres kontrak menunjukkan 80%, sedangkan bukti lapangan yang diterima mengindikasikan sekitar 40%. PPK meminta KPPN segera menyimpulkan siapa yang bersalah.',
d:[['Klarifikasi perbedaan bukti melalui pejabat berwenang dan jaga pengujian tagihan tanpa mengambil alih penilaian kontrak.','Pimpinan membedakan indikasi, pembuktian, dan kewenangan.'],['Tetapkan fraud hanya dari dua persentase yang berbeda.','Perbedaan memerlukan penelusuran definisi dan bukti.'],['Terima angka tertinggi agar proyek tidak terganggu.','Kenyamanan layanan tidak mengalahkan validitas.'],['Kepala KPPN mengesahkan sendiri prestasi pekerjaan.','Tanggung jawab substantif tidak otomatis beralih.']],
m:[['Tinjau hasil klarifikasi, dasar prestasi yang sah, keputusan pembayaran, dan eskalasi bila diperlukan.','Pengendalian mengikuti bukti serta kewenangan.'],['Nilai dari cepatnya pihak tertentu diberi sanksi.','Sanksi memerlukan proses dan otoritas.'],['Anggap laporan selesai jika kedua angka dibuat sama.','Penyamaan angka tanpa bukti bukan penyelesaian.'],['Hentikan jejak audit setelah perbedaan dibahas lisan.','Pembahasan perlu dokumentasi yang dapat ditelusuri.']]},
{p:9,ref:'K-16',s:'Program prioritas tertunda karena izin lokasi Pemda belum selesai. PPK meminta Kepala KPPN memerintahkan kepala daerah menerbitkan izin dan mempercepat pembayaran kontrak.',
d:[['Fasilitasi koordinasi hambatan dan eskalasi tepat, sambil menjaga pembayaran sesuai hak tagih.','Prioritas nasional tidak menghapus batas kewenangan.'],['Perintahkan izin terbit atas nama kewenangan pencairan.','Kewenangan pembayaran tidak sama dengan penerbitan izin.'],['Bayar dahulu agar Pemda tertekan menyelesaikan izin.','Pembayaran tidak boleh menjadi alat tekanan di luar syarat.'],['Anggap program bukan lagi tanggung jawab koordinasi karena terkait Pemda.','Koordinasi masih dapat dilakukan sesuai mandat.']],
m:[['Pantau keputusan pihak berwenang, milestone izin, dan dampaknya pada jadwal pekerjaan yang sah.','Ukuran hasil mengikuti rantai penyelesaian hambatan.'],['Nilai dari jumlah instruksi KPPN kepada Pemda.','Instruksi di luar mandat bukan capaian.'],['Gunakan serapan sebagai bukti izin sudah sah.','Pembayaran tidak membuktikan legalitas izin.'],['Tutup risiko setelah rapat lintas instansi pertama.','Rapat belum menjamin hambatan terselesaikan.']]},
{p:9,ref:'K-27',s:'Pejabat senior meminta operator menurunkan severity EWS sebelum kunjungan pengawas. Tidak ada data baru dan rule belum diubah melalui persetujuan pemilik proses.',
d:[['Tolak perubahan tanpa dasar, dokumentasikan permintaan, dan gunakan jalur eskalasi yang tepat.','Integritas memerlukan keputusan serta jejak penanganan tekanan.'],['Ubah sementara dan pulihkan setelah kunjungan selesai.','Manipulasi sementara tetap merusak informasi.'],['Serahkan keputusan kepada operator agar kepala kantor netral.','Pimpinan tidak boleh melepaskan tanggung jawab pengendalian.'],['Hapus dashboard sepenuhnya agar permintaan tidak relevan.','Menghilangkan alat tanpa menyelesaikan tekanan bukan solusi proporsional.']],
m:[['Pastikan versi rule dan data tetap dapat ditelusuri serta permintaan tidak sah ditangani.','Kontrol harus mencegah perubahan tersembunyi.'],['Nilai dari penilaian pengawas yang terlihat baik saja.','Citra baik tidak membuktikan integritas data.'],['Pastikan tidak ada catatan permintaan pejabat senior.','Penghilangan bukti melemahkan akuntabilitas.'],['Anggap operator sudah aman setelah menerima perintah lisan.','Perintah lisan tidak membenarkan tindakan tidak sah.']]},
{p:9,ref:'K-19, M1',s:'Ada indikasi pembayaran tidak berhak. Tim mengusulkan meminta pengembalian segera dan menutup kasus begitu uang masuk, sebelum status bukti serta proses pertanggungjawaban diperiksa.',
d:[['Amankan bukti, koordinasikan pemeriksaan berwenang, dan bedakan pemulihan dana dari proses pertanggungjawaban.','Pengembalian tidak otomatis mengakhiri seluruh aspek kasus.'],['Tutup kasus otomatis setelah dana dikembalikan.','Pemulihan dana tidak selalu menyelesaikan kewajiban proses.'],['Umumkan pelaku sebelum bukti diperiksa.','Indikasi belum cukup untuk kesimpulan personal.'],['Tunda pengamanan bukti hingga semua pihak sepakat.','Penundaan dapat menghilangkan bukti penting.']],
m:[['Pantau status bukti, pemulihan yang sah, serta penyelesaian melalui pejabat dan mekanisme berwenang.','Hasil harus mencakup pemulihan dan akuntabilitas.'],['Gunakan nominal kembali sebagai satu-satunya indikator selesai.','Nominal tidak menjawab seluruh kewajiban proses.'],['Nilai dari banyaknya pengakuan lisan tanpa dokumen.','Pengakuan lisan tidak menggantikan pemeriksaan bukti.'],['Hapus data transaksi setelah uang diterima kembali.','Riwayat tetap diperlukan untuk pertanggungjawaban.']]},
{p:9,ref:'K-30, M1',s:'Kepala KPPN diminta menandatangani semua keputusan pembinaan dan koreksi teknis sendiri. Alasannya, delegasi dianggap mengurangi tanggung jawab pimpinan. Antrean keputusan mulai menumpuk.',
d:[['Tetapkan batas delegasi, hasil yang diharapkan, tenggat, dan pengawasan sesuai kewenangan masing-masing.','Delegasi terkontrol mendukung akuntabilitas, bukan menghilangkannya.'],['Ambil seluruh pekerjaan teknis agar tanggung jawab terlihat jelas.','Sentralisasi berlebihan menciptakan bottleneck.'],['Serahkan semua keputusan tanpa batas kepada staf paling senior.','Delegasi memerlukan kejelasan ruang dan kontrol.'],['Minta setiap masalah rutin diputuskan Kanwil.','Eskalasi tidak menggantikan keputusan dalam kewenangan kantor.']],
m:[['Tinjau mutu hasil, waktu penyelesaian, pengecualian, dan kasus yang memerlukan keputusan pimpinan.','Pengawasan menguji hasil serta batas delegasi.'],['Nilai dari jumlah tanda tangan Kepala KPPN per hari.','Volume tanda tangan bukan kualitas kepemimpinan.'],['Anggap pekerjaan selesai saat surat tugas diterbitkan.','Penugasan belum membuktikan hasil.'],['Ukur keberhasilan dari tidak adanya keputusan yang diambil staf.','Ketiadaan delegasi justru dapat menghambat organisasi.']]}
];
